#!/bin/bash

# This sourced fragment supplies one argv element per compiler flag.
# shellcheck disable=SC2034
# >>> shguard modes=source (generated by shell-disposition-gate --guard; do not edit)
case $(realpath -- "$0" 2>/dev/null) in */'tools/build_system/build-flags.sh') _shguard_m='exec' ;; *) if [ "${SHGUARD_MODE-}" = 'pipe' ]; then _shguard_m='pipe'; else _shguard_m='source'; fi ;; esac
# shellcheck disable=SC2317
case $_shguard_m in
  source) unset _shguard_m ;;
  *) printf '%s: refusing %s invocation (supports: source; pipe callers set SHGUARD_MODE=pipe)\n' 'build-flags.sh' "$_shguard_m" >&2; unset _shguard_m; return 1 2>/dev/null || exit 1 ;;
esac
# <<< shguard
gcc_flags=(
	-Wall
	-Werror
	-Wno-unused-variable
	-Wno-unused-label
	-Wno-parentheses
	-Wno-comment
)

